  "steps": [
    {
      "id": 1,
      "claim": "Atmospheric pressure decreases with altitude.",
      "evidence": "Barometric formula: pressure ≈ 101 kPa at sea level and ≈ 80 kPa at typical high‑mountain elevations (~2–3 km).",
      "weight": 0.20,
      "depends_on": []
    },
    {
      "id": 2,
      "claim": "When the bottle was open on the summit, the air inside it was at the same low pressure as the outside atmosphere.",
      "evidence": "An open container equilibrates its internal pressure with the surrounding air.",
      "weight": 0.20,
      "depends_on": [1]
    },
    {
      "id": 3,
      "claim": "After the water was drunk, the bottle was sealed, trapping that low‑pressure air inside.",
      "evidence": "The cap was replaced while the bottle was empty, fixing the amount of gas and its pressure at the summit value.",
      "weight": 0.15,
      "depends_on": [2]
    },
    {
      "id": 4,
      "claim": "Descending to the valley raises the external atmospheric pressure to near sea‑level values.",
      "evidence": "Pressure increases as altitude decreases; typical valley pressure ≈ 101 kPa, higher than the ≈80 kPa at the summit.",
      "weight": 0.20,
      "depends_on": [1]
    },
    {
      "id": 5,
      "claim": "The resulting pressure difference (~20 kPa) exceeds the critical buckling pressure of a thin‑walled plastic bottle, causing it to collapse inward.",
      "evidence": "Thin‑walled spherical or cylindrical shells buckle when external‑minus‑internal pressure exceeds ~10–15 kPa for common PET bottles; experimental demonstrations show collapse with a ~20 kPa over‑pressure.",
      "weight": 0.25,
      "depends_on": [3, 4]
    }
  ],
  "answer": "D",
  "confidence": 0.98,
  "considered": [
    {
      "answer": "A",
      "reason_rejected": "Temperature differences alone would not create a net pressure imbalance large enough to crush the bottle; the dominant effect is the change in ambient pressure with altitude."
    },
    {
      "answer": "B",
      "reason_rejected": "Higher temperature in the valley would increase internal pressure, opposing collapse rather than causing it."
    },
    {
      "answer": "C",
      "reason_rejected": "Air pressure is higher in valleys (lower altitude) than on mountain tops; this statement is factually incorrect."
    }
  ]
}
